import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

const PRIMARY = '#EA580C';
const PRIMARY_LIGHT = '#FFF4EE'; // light tint for active state bg
const PRIMARY_TEXT = '#EA580C';  // active nav text

export type NavItem = {
  id: string;
  label: string;
  path: string;
  icon?: string;
};
export type NavGroup = {
  id: string;
  label: string;
 path: string;
  icon?: string;
  children?: NavItem[];
};

interface SidebarProps {
  features: NavItem[];
  collapsed?: boolean;
  onToggle?: () => void;
  onNavigate?: (item: NavItem) => void;
}

// Weera logo image
const WeeraIcon: React.FC<{ size?: number }> = ({ size = 22 }) => (
  <img
    src="/images/app_icon_fg.png"
    width={size}
    height={size}
    alt="Weera logo"
    style={{ objectFit: 'contain', display: 'block' }}
  />
);

export const Sidebar: React.FC<SidebarProps> = ({
  features,
  collapsed = false,
  onToggle,
  onNavigate,
}) => {
  const navigate = useNavigate();
  const location = useLocation();
  const width = collapsed ? 56 : 280;

  const handleClick = (item: NavItem) => {
    navigate(item.path);
    onNavigate?.(item);
  };

  return (
    <aside style={{
      width,
      minWidth: width,
      height: '100vh',
      background: '#F9FBFC',
      borderRight: '1px solid #E1E4EA',
      boxSizing: 'border-box',
      padding: collapsed ? '12px 8px' : '12px 16px 12px 12px',
      display: 'flex',
      flexDirection: 'column',
      gap: 24,
      transition: 'width 0.25s ease, min-width 0.25s ease, padding 0.25s ease',
      overflow: 'hidden',
      position: 'fixed',
      top: 0,
      left: 0,
      zIndex: 100,
    }}>
      {/* Logo + hamburger */}
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: collapsed ? 'center' : 'space-between',
        gap: 8,
        padding: '4px 4px 0',
      }}>
        {!collapsed && (
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: 8,
            whiteSpace: 'nowrap',
          }}>
            {/* Logo icon with primary background */}
            <div style={{
              width: 32,
              height: 32,
              borderRadius: 8,
              background: PRIMARY,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              flexShrink: 0,
              boxShadow: `0 2px 8px ${PRIMARY}55`,
            }}>
              <WeeraIcon size={28} />
            </div>
            <span style={{ fontSize: 15, fontWeight: 700, color: '#0f172a', letterSpacing: '0.02em' }}>
              WEERA
            </span>
          </div>
        )}

        {collapsed && (
          <div style={{
            width: 32,
            height: 32,
            borderRadius: 8,
            background: PRIMARY,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            flexShrink: 0,
            marginBottom: 4,
            boxShadow: `0 2px 8px ${PRIMARY}55`,
          }}>
            <WeeraIcon size={28} />
          </div>
        )}

        <button
          onClick={onToggle}
          aria-label="Toggle sidebar"
          style={{
            background: 'none',
            border: '1px solid #E1E4EA',
            borderRadius: 8,
            cursor: 'pointer',
            padding: '6px 8px',
            display: 'flex',
            flexDirection: 'column',
            gap: 4,
            alignItems: 'center',
            flexShrink: 0,
          }}
        >
          <span style={{ display: 'block', width: 16, height: 2, background: '#4B5565', borderRadius: 2 }} />
          <span style={{ display: 'block', width: 16, height: 2, background: '#4B5565', borderRadius: 2 }} />
          <span style={{ display: 'block', width: 16, height: 2, background: '#4B5565', borderRadius: 2 }} />
        </button>
      </div>

      {/* Nav links */}
      <nav style={{ flex: 1 }}>
        <ul style={{ listStyle: 'none', padding: 0, margin: 0, display: 'flex', flexDirection: 'column', gap: 4 }}>
          {features.map(group => (
  <React.Fragment key={group.id}>
    <li>
      <button
        onClick={() =>
          handleClick({
            id: group.id,
            label: group.label,
            path: group.path,
            icon: group.icon,
          })
        }
      >
        <span>{group.icon}</span>
        {!collapsed && <span>{group.label}</span>}
      </button>
    </li>

    {group.children?.map(child => (
      <li key={child.id} style={{ paddingLeft: collapsed ? 0 : 20 }}>
        <button onClick={() => handleClick(child)}>
          <span>{child.icon}</span>
          {!collapsed && <span>{child.label}</span>}
        </button>
      </li>
    ))}
  </React.Fragment>
))}
        </ul>
      </nav>
    </aside>
  );
};

export default Sidebar;
